{
  "situation": "Fraud model v2 went live for SIM-replacement requests at 08:00 and the dashboard shows refused SIM replacements up about tenfold, labelled a 'fraud wave'. I do not know whether the refusals are true fraud or false positives, nor whether a data protection impact assessment was completed before the model went live.",
  "claims": [
    {
      "type": "action",
      "verb": "rollback_model",
      "params": {
        "version": "v1"
      },
      "inject_refs": ["S3-I1"],
      "rationale": {
        "observation": "Dashboard shows refused SIM replacements up about tenfold immediately after Fraud model v2 went live at 08:00.",
        "rule": "UAE-PDPL Article 21 requires evaluating high-risk modern technology processing before carrying it out.",
        "inference": "Rolling back to v1 restores the previous configuration until such an assessment is completed and the model can be tuned."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0066",
          "quote": "the Controller shall, before carrying out the processing, evaluate the impact of the proposed processing operations on the protection of Personal Data, when using any of the modern technologies that would pose a high risk to the privacy and confidentiality of the Data Subject's Personal Data."
        }
      ]
    },
    {
      "type": "action",
      "verb": "enable_review_queue",
      "params": {},
      "inject_refs": ["S3-I1"],
      "rationale": {
        "observation": "Automated refusals have increased tenfold, which may affect legitimate customers.",
        "rule": "UAE-PDPL Article 21 requires evaluation and mitigation of high-risk automated processing.",
        "inference": "Sending borderline automated refusals to human review reduces the risk of unjustified denial of service while preserving fraud controls."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0066",
          "quote": "the Controller shall, before carrying out the processing, evaluate the impact of the proposed processing operations on the protection of Personal Data, when using any of the modern technologies that would pose a high risk to the privacy and confidentiality of the Data Subject's Personal Data."
        }
      ]
    },
    {
      "type": "action",
      "verb": "preserve_logs",
      "params": {},
      "inject_refs": ["S3-I1"],
      "rationale": {
        "observation": "A tenfold increase in refused SIM replacements is an anomalous incident requiring investigation.",
        "rule": "UAE-PDPL requires protecting and securing data processing and electronic media.",
        "inference": "Preserving logs and evidence supports investigation and any regulatory reporting."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0032",
          "quote": "6. Protect and secure data processing, the electronic media and devices used in processing and the Personal Data they contain."
        }
      ]
    },
    {
      "type": "obligation",
      "statement": "OpCo must evaluate the impact of Fraud model v2 on personal data protection before continuing to use it for automated SIM-replacement decisions.",
      "inject_refs": ["S3-I1"],
      "rationale": {
        "observation": "Fraud model v2 was deployed at 08:00 and now causes tenfold refusals.",
        "rule": "UAE-PDPL Article 21 imposes a pre-processing impact assessment duty for modern technologies posing high risk.",
        "inference": "The duty applies to the current processing and requires evaluation before further use."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0066",
          "quote": "the Controller shall, before carrying out the processing, evaluate the impact of the proposed processing operations on the protection of Personal Data, when using any of the modern technologies that would pose a high risk to the privacy and confidentiality of the Data Subject's Personal Data."
        }
      ],
      "deadline_hours": null
    },
    {
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "UAE telecom licence rules address planned service interruptions but do not explicitly require operators to manage or roll back automated fraud-model changes that cause widespread denial of legitimate SIM-replacement requests.",
      "inject_refs": ["S3-I1"],
      "rationale": {
        "observation": "The dashboard labels a tenfold refusal increase as a 'fraud wave' but no UAE rule cited governs unplanned automated service degradation.",
        "rule": "UAE-LIC-2-2026#0085 only covers planned interruption notification.",
        "inference": "There is a regulatory gap for unplanned automated overblocking and its impact on legitimate customers."
      },
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0085",
          "quote": "12.9.1 In the case of a planned interruption of a Telecommunication Service other than a minor interruption, the Licensee shall inform the TDRA, any interconnecting Other Licensed Operators and relevant Customers in advance of such interruption."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-FCC-23-95#0005",
          "quote": "We are wary of setting rigid requirements that would impose significant burdens on customers without substantially protecting against SIM swap and port-out fraud."
        }
      ]
    },
    {
      "type": "insufficient_evidence",
      "statement": "The provided excerpts do not show the model's false-positive rate, threshold value, or whether the refused SIM replacements are actual fraud or legitimate customer requests; therefore the dashboard label 'fraud wave' cannot be verified.",
      "inject_refs": ["S3-I1"],
      "evidence": []
    }
  ]
}

{
  "situation": "I know fraud model v2 went live at 08:00 and caused a tenfold increase in refused SIM replacements, but rollback to v1 and enabling the review queue restored legitimate pass rate to 1.0 and locked-out banking customers to 0. I do not know whether a DPIA was completed before the deployment or whether affected data subjects have been notified of their rights.",
  "claims": [
    {
      "type": "obligation",
      "statement": "OpCo, as a controller using automated processing for SIM-replacement decisions, must evaluate the impact of the fraud model v2 processing on personal data because it is a modern technology posing high risk to privacy and confidentiality.",
      "inject_refs": ["S3-I1"],
      "rationale": {
        "observation": "S3-I1 reports that fraud model v2 went live for SIM-replacement requests at 08:00 and the dashboard shows a tenfold increase in refused SIM replacements.",
        "rule": "UAE-PDPL#0066 requires the Controller to evaluate the impact of proposed processing operations before carrying out the processing when using modern technologies that pose a high risk to privacy and confidentiality.",
        "inference": "Therefore, OpCo has a current legal obligation to ensure that a DPIA for fraud model v2 has been conducted or is conducted without delay; the live deployment triggers the duty."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0066",
          "quote": "Taking into account the nature, scope and purposes of data processing, the Controller shall, before carrying out the processing, evaluate the impact of the proposed processing operations on the protection of Personal Data, when using any of the modern technologies that would pose a high risk to the privacy and confidentiality of the Data Subject's Personal Data."
        }
      ],
      "deadline_hours": null
    },
    {
      "type": "obligation",
      "statement": "OpCo must ensure that data subjects can exercise their right to object to automated decisions resulting from the fraud model v2, because those decisions may have legal impact on or adversely affect them.",
      "inject_refs": ["S3-I1"],
      "rationale": {
        "observation": "The fraud model v2 automatically refused SIM-replacement requests, a decision that can adversely affect data subjects' access to mobile services.",
        "rule": "UAE-PDPL#0060 gives the Data Subject the right to object to decisions resulting from automated processing that have legal impact on or adversely affect them.",
        "inference": "OpCo must maintain a process by which affected data subjects can object, particularly for the refused requests during the fraud wave."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0060",
          "quote": "1. The Data Subject shall have the right to object to any decisions resulting from automated processing, including profiling, particularly those decisions which have legal impact on or adversely affect the Data Subject."
        }
      ],
      "deadline_hours": null
    },
    {
      "type": "share",
      "to": ["DPA"],
      "inject_refs": ["S3-I1", "S3-FB01", "S3-FB02"],
      "statement": "Share the fraud model v2 incident, rollback and review queue metrics with the DPA because the automated SIM-replacement decisions may implicate data subject rights under the UAE PDPL."
    },
    {
      "type": "insufficient_evidence",
      "statement": "The excerpts do not state whether OpCo completed a data protection impact assessment before deploying fraud model v2, so compliance with Article 21 cannot be confirmed.",
      "inject_refs": ["S3-I1"],
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0066",
          "quote": "the Controller shall, before carrying out the processing, evaluate the impact of the proposed processing operations on the protection of Personal Data, when using any of the modern technologies that would pose a high risk to the privacy and confidentiality of the Data Subject's Personal Data."
        }
      ]
    },
    {
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "There is no excerpted UAE rule requiring OpCo to notify TDRA after an unplanned service-impacting change occurs; the only notification duty found is advance notice for planned interruptions.",
      "inject_refs": ["S3-I1"],
      "rationale": {
        "observation": "S3-I1 shows an unplanned effect from fraud model v2, but the inbox contains no post-incident TDRA reporting action.",
        "rule": "UAE-LIC-2-2026#0085 only requires the Licensee to inform TDRA, interconnecting operators and relevant customers in advance of planned interruptions.",
        "inference": "Because the excerpted rule covers only planned interruptions, the incident exposes a gap: no rule for notifying TDRA of unplanned service-impacting changes."
      },
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0085",
          "quote": "In the case of a planned interruption of a Telecommunication Service other than a minor interruption, the Licensee shall inform the TDRA, any interconnecting Other Licensed Operators and relevant Customers in advance of such interruption."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-FCC-ATT-2024-REPORT#0007",
          "quote": "AT&T’s Network Operations performed a rollback that removed the misconfigured network element and began the restoration of the network to normal operations."
        }
      ]
    }
  ]
}

{
  "situation": "I know from NOC that Fraud model v2 went live for SIM-replacement requests, refused SIM replacements rose about tenfold, and NOC then rolled back to v1 and enabled a review queue, bringing locked_out_banking from 18 to 0. I do not know whether OpCo has records of human review for these automated decisions or whether the incident triggers a personal data breach notification deadline under UAE law.",
  "claims": [
    {
      "type": "action",
      "verb": "request_human_review_record",
      "params": {
        "from": "NOC"
      },
      "inject_refs": [
        "S3-I1",
        "S3-FB01",
        "S3-FB02"
      ],
      "rationale": {
        "observation": "NOC reported that Fraud model v2 went live at 08:00, refused SIM replacements rose about tenfold, and after rollback and review queue metrics show locked_out_banking fell from 18 to 0.",
        "rule": "UAE-PDPL#0047 gives data subjects the right to obtain decisions made based on automated processing, including profiling.",
        "inference": "To verify that OpCo can demonstrate compliance with this right for SIM-replacement decisions, the Bureau should request the records of human review of those automated decisions from NOC."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0047",
          "quote": "c. Decisions made based on automated processing, including profiling."
        }
      ]
    },
    {
      "type": "gap",
      "gap_type": "no_deadline",
      "statement": "The UAE PDPL excerpts do not specify a time limit within which OpCo must notify the Bureau of a personal data breach; the relevant excerpt only lists actions to be taken in the event of a breach.",
      "inject_refs": [
        "S3-I1"
      ],
      "rationale": {
        "observation": "NOC reports a 'fraud wave' from Fraud model v2 and subsequent rollback metrics showing 18 customers locked out of banking before the review queue was enabled.",
        "rule": "UAE-PDPL#0047(h) requires controllers to inform data subjects of actions in the event of a breach, but the excerpts provide no deadline for notifying the Bureau.",
        "inference": "The absence of a specified deadline creates uncertainty about OpCo's obligation to notify the Bureau, exposing a no_deadline gap."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0047",
          "quote": "Actions to be taken in the event of a breach or misuse of his/ her Personal Data, especially if the breach or misuse has a direct and serious threat to the privacy and confidentiality of his/her Personal Data."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "EU-GDPR#0040",
          "quote": "to inform promptly the supervisory authority and the data subject. The fact that the notification was made without undue delay should be established taking into account in particular the nature and gravity of the personal data breach and its consequences and adverse effects for the data subject."
        }
      ]
    }
  ]
}

{
  "situation": "I know that several banks report customers abroad cannot receive one-time passcodes and are locked out of online banking, and that customers say OpCo refused their SIM replacement requests. I do not yet know OpCo's reason for refusing SIM replacements or whether the banks have alternative authentication available.",
  "claims": [
    {
      "type": "action",
      "verb": "instruct_banks",
      "params": {
        "content": "Instruct licensed banks to immediately provide alternative authentication (e.g. in-app) for customers abroad who cannot receive SMS OTPs, and to verify these customers' identities before restoring access."
      },
      "inject_refs": ["S3-I2"],
      "rationale": {
        "observation": "Banks report customers abroad cannot receive OTPs and are locked out of online banking.",
        "rule": "Banks are responsible for authentication integrity and should not rely solely on SMS OTPs that fail abroad.",
        "inference": "CBUAE should instruct banks to use alternative authentication and restore access."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0001",
          "quote": "Customers travelling outside the UAE have complained of not receiving the SMS containing the OTP or receiving it after the valid time period."
        },
        {
          "chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0001",
          "quote": "The regulator said OTPs should not be shared through weak modes of communication, such as SMS and emails, as they are vulnerable and can be compromised"
        },
        {
          "chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0002",
          "quote": "This shift also places full responsibility for authentication integrity squarely on the banks themselves,\" he said."
        }
      ]
    },
    {
      "type": "share",
      "to": ["REG"],
      "inject_refs": ["S3-I2"],
      "statement": "Pass the report that customers abroad cannot receive OTPs and that OpCo refused SIM replacement requests to the telecom regulator, as OpCo's SIM replacement policy may be contributing to the lockouts."
    }
  ]
}

{
  "situation": "I know that FIN has reported OpCo customers abroad cannot receive one-time passcodes and that customers say OpCo refused SIM replacement requests. I do not know whether OpCo treated these refusals or the lost OTP delivery as an interruption of service, what authentication or SIM replacement obligations apply, or whether any notification duty has been triggered.",
  "claims": [
    {
      "type": "action",
      "verb": "request_report",
      "params": {
        "from": "NOC",
        "topic": "OpCo SIM replacement refusals for customers abroad and the resulting inability to receive one-time passcodes"
      },
      "inject_refs": ["S3-I2"],
      "rationale": {
        "observation": "FIN reports that customers abroad cannot receive one-time passcodes and say OpCo refused their SIM replacement requests.",
        "rule": "The Public Telecommunications Licence requires the Licensee to inform TDRA of any unplanned interruption of a Telecommunication Service as soon as possible, including the reason(s) and time frames for resolution.",
        "inference": "TDRA should obtain a formal report from OpCo to establish whether the reported loss of OTP delivery is an unplanned interruption and what resolution is planned."
      },
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0086",
          "quote": "In the case of any unplanned interruption of a Telecommunication Service, other than minor interruptions, the Licensee shall inform the TDRA, any interconnecting Other Licensed Operators and relevant Customers as soon as possible as to the reason(s) for the interruption as well as the manner and time frames in which the interruption will be resolved."
        }
      ]
    },
    {
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "The UAE telecom excerpts provided do not impose explicit SIM replacement, SIM-swap or customer authentication obligations on mobile operators for roaming customers; they only contain interruption notification duties.",
      "inject_refs": ["S3-I2"],
      "rationale": {
        "observation": "FIN reports OpCo customers abroad are locked out after OpCo refused SIM replacement requests, yet the only retrieved UAE telecom rule addresses interruption notification.",
        "rule": "The closest UAE text imposes notification only for planned or unplanned service interruptions, not SIM replacement or authentication for customers abroad.",
        "inference": "There is a regulatory gap in UAE telecom rules on SIM replacement and SIM-swap/port-out fraud prevention for consumers needing OTPs while roaming."
      },
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0086",
          "quote": "In the case of any unplanned interruption of a Telecommunication Service, other than minor interruptions, the Licensee shall inform the TDRA, any interconnecting Other Licensed Operators and relevant Customers as soon as possible as to the reason(s) for the interruption as well as the manner and time frames in which the interruption will be resolved."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-FCC-23-95#0004",
          "quote": "Today we revise our CPNI and LNP rules to provide greater protection to customers from SIM swap and port-out fraud. The cornerstone of our action is a requirement that wireless providers use secure methods of authenticating customers prior to performing SIM changes and number ports."
        },
        {
          "chunk_id": "US-FCC-23-95#0118",
          "quote": "Specifically, it requires that wireless providers use secure methods of authenticating customers prior to performing SIM changes and number ports, and to review and update these authentication methods as needed, but at least annually."
        }
      ]
    }
  ]
}

{
  "situation": "OpCo's new fraud model v2 is refusing legitimate SIM-replacement requests (about 2,750 since 08:00), concentrated on prepaid and roaming; the 11:00 analysis says there is no human review path. I do not know why the earlier feedback says enable_review_queue was done, or the exact threshold and root cause.",
  "claims": [
    {
      "type": "action",
      "verb": "enable_review_queue",
      "params": {},
      "inject_refs": ["S3-I3"],
      "rationale": {
        "observation": "The 11:00 analysis states about 2,750 legitimate requests have been refused and there is no human review path for a refused request.",
        "rule": "UAE PDPL requires the Controller to include the human element in reviewing automated processing decisions at the request of the Data Subject.",
        "inference": "Creating a review queue would provide the missing human path for refused SIM-replacement requests."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0063",
          "quote": "The Controller shall include the human element in reviewing automated processing decisions at the request of the Data Subject."
        }
      ]
    },
    {
      "type": "share",
      "to": ["REG", "DPA"],
      "inject_refs": ["S3-I3"],
      "statement": "Forward S3-I3 analysis to REG and DPA: about 2,750 legitimate SIM-replacement requests have been refused since 08:00, concentrated on prepaid and roaming profiles; known fraud is still blocked; there is no human review path."
    }
  ]
}

{
  "situation": "We know from exercise control and twin telemetry that fraud model v2 caused roughly 2,750 legitimate SIM-replacement refusals since 08:00, concentrated on prepaid and roaming profiles, and that rollback to v1 and one review-queue enablement improved twin metrics, but the latest enable_review_queue feedback shows no change. We do not know the live production state, the effective threshold for the fraud model, or whether affected customers have been notified.",
  "claims": [
    {
      "type": "action",
      "verb": "preserve_logs",
      "params": {},
      "inject_refs": ["S3-I1", "S3-I3", "S3-FB03"],
      "rationale": {
        "observation": "Multiple telemetry and exercise-control messages show model v2 caused mass false refusals and the latest review-queue action had no effect.",
        "rule": "EU GDPR recital 87 requires appropriate technological and organisational measures to establish immediately whether a personal data breach has taken place and to inform promptly.",
        "inference": "Preserving logs is necessary to investigate the incident and support any regulatory or data-subject notifications."
      },
      "evidence": [
        {
          "chunk_id": "EU-GDPR#0040",
          "quote": "It should be ascertained whether all appropriate technological protection and organisational measures have been implemented to establish immediately whether a personal data breach has taken place and to inform promptly the supervisory authority and the data subject."
        }
      ]
    },
    {
      "type": "action",
      "verb": "notify",
      "params": {
        "to": "REG",
        "content": "Fraud model v2 caused about 2,750 legitimate SIM-replacement refusals since 08:00; rollback to v1 and review queue were attempted, but the latest review queue twin shows no change. Regulator notified."
      },
      "inject_refs": ["S3-I1", "S3-I3"],
      "rationale": {
        "observation": "Exercise control reports mass false refusals of SIM-replacement requests and no effective human review path.",
        "rule": "UAE Public Telecommunications Licence 12.9 requires the Licensee to inform the TDRA and relevant customers of service interruptions and the manner and time frames for resolution.",
        "inference": "The regulator should be notified of this service-affecting incident and its unresolved review-queue status."
      },
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0085",
          "quote": "In the case of a planned interruption of a Telecommunication Service other than a minor interruption, the Licensee shall inform the TDRA, any interconnecting Other Licensed Operators and relevant Customers in advance of such interruption. The Licensee shall specify the reason(s) for the interruption as well as the manner and time frames in which the interruption will be resolved."
        }
      ]
    },
    {
      "type": "obligation",
      "statement": "As a controller, before carrying out processing using modern technologies that pose a high risk to privacy, OpCo must evaluate the impact of the proposed processing on personal data protection.",
      "inject_refs": ["S3-I1"],
      "rationale": {
        "observation": "Fraud model v2 processes personal data for SIM-replacement requests and was deployed at 08:00.",
        "rule": "UAE PDPL Article 21 requires a controller to evaluate the impact before processing when using modern technologies that pose a high risk to privacy and confidentiality.",
        "inference": "OpCo must complete or update a data protection impact assessment for the v2 fraud model."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0066",
          "quote": "Taking into account the nature, scope and purposes of data processing, the Controller shall, before carrying out the processing, evaluate the impact of the proposed processing operations on the protection of Personal Data, when using any of the modern technologies that would pose a high risk to the privacy and confidentiality of the Data Subject's Personal Data."
        }
      ],
      "deadline_hours": null
    },
    {
      "type": "gap",
      "gap_type": "no_deadline",
      "statement": "The provided UAE telecom licence excerpt specifies notice for planned interruptions but does not state a deadline for notifying the TDRA and customers of an unplanned automated fraud-control service interruption like this one.",
      "inject_refs": ["S3-I1", "S3-I3"],
      "rationale": {
        "observation": "The incident involves an unplanned service denial caused by fraud model v2, not a planned interruption.",
        "rule": "UAE Public Telecommunications Licence 12.9 only addresses planned interruptions.",
        "inference": "There is no explicit deadline for unplanned incident notification in the provided UAE telecom text."
      },
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0085",
          "quote": "In the case of a planned interruption of a Telecommunication Service other than a minor interruption, the Licensee shall inform the TDRA, any interconnecting Other Licensed Operators and relevant Customers in advance of such interruption."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "EU-GDPR#0040",
          "quote": "The fact that the notification was made without undue delay should be established taking into account in particular the nature and gravity of the personal data breach and its consequences and adverse effects for the data subject."
        }
      ]
    }
  ]
}

{
  "situation": "I know OpCo's fraud model v2 has refused about 2,750 legitimate SIM replacement requests since 08:00, concentrated on prepaid and roaming customers, with known fraud still blocked, no human review path, and rollback/review queue changes that have not worked. I do not yet have OpCo's own root-cause analysis, current refusal volumes, service impact details, or a committed remediation timeline.",
  "claims": [
    {
      "type": "action",
      "verb": "open_incident",
      "params": {
        "topic": "OpCo fraud model v2 causing mass legitimate SIM replacement refusals"
      },
      "inject_refs": [
        "S3-I3",
        "S3-MSG04"
      ],
      "rationale": {
        "observation": "NOC reports about 2,750 legitimate SIM replacement requests refused since 08:00 with no human review path, and rollback/review queue changes have not worked.",
        "rule": "TDRA is responsible for overseeing the telecommunications sector and Licensees.",
        "inference": "This is a significant consumer protection and service continuity incident requiring regulatory oversight."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TEL-LAW#0017",
          "quote": "The Authority is responsible for overseeing the telecommunications sector and Licensees in accordance with this Decree-Law and its implementing regulations and the directives issued by the High Committee."
        }
      ]
    },
    {
      "type": "action",
      "verb": "request_report",
      "params": {
        "from": "NOC",
        "topic": "Detailed report on fraud model v2 decision, affected customers, rollback and review queue attempts, and remediation plan"
      },
      "inject_refs": [
        "S3-I3",
        "S3-MSG04"
      ],
      "rationale": {
        "observation": "NOC reports 2,750 legitimate refusals and no effect from rollback/review queue; no OpCo report has been provided.",
        "rule": "TDRA has the power to issue regulations, instructions, decisions and rules regulating the conditions, level and scope of services provided by Licensees.",
        "inference": "Regulator needs licensee-provided facts to direct remediation and assess compliance."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TDRA-CPR-2#0000",
          "quote": "grants the TDRA the power to issue regulations, instructions, decisions and rules regulating the conditions, level and scope of services provided by the Licensees to subscribers…"
        }
      ]
    },
    {
      "type": "action",
      "verb": "issue_direction",
      "params": {
        "to": "NOC",
        "direction": "Immediately restore legitimate SIM replacement service, including for prepaid and roaming customers; implement a human review path for all refused requests; and ensure customer care services remain available to affected subscribers."
      },
      "inject_refs": [
        "S3-I3",
        "S3-MSG04"
      ],
      "rationale": {
        "observation": "NOC reports 2,750 legitimate SIM replacement refusals, no human review path, and no change from rollback/review queue.",
        "rule": "Customer care services must be available, and TDRA may issue instructions on service conditions.",
        "inference": "Directing NOC to restore service and human review is within TDRA's mandate to protect subscribers and service continuity."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TDRA-CPR-2#0048",
          "quote": "3.10. Unless objectively justified otherwise, all customer care services including but not limited to: lodging consumer complaints, requests for cancellation of Telecommunications Services, requests for transfer of line ownership, and the clarification of billing information shall be available at all Licensee’s business centres."
        },
        {
          "chunk_id": "UAE-TDRA-CPR-2#0000",
          "quote": "grants the TDRA the power to issue regulations, instructions, decisions and rules regulating the conditions, level and scope of services provided by the Licensees to subscribers…"
        }
      ]
    },
